xpath.script:
document.addEventListener("DOMContentLoaded", function () {

    const form = document.querySelector("form.o_portal_details");
    if (!form) return;

    const phoneInput = form.querySelector('input[name="phone"]');
    if (!phoneInput) return;

    // Create error message element once
    let errorEl = document.createElement("div");
    errorEl.className = "invalid-feedback d-block";
    errorEl.style.display = "none";
    errorEl.innerText =
        "Phone number must include country code, e.g. +27XXXXXXXXX";

    phoneInput.parentNode.appendChild(errorEl);

    function isValidPhone(value) {
        return /^\+\d{7,15}$/.test(value);
    }

    function showError() {
        phoneInput.classList.add("is-invalid");
        errorEl.style.display = "block";
    }

    function clearError() {
        phoneInput.classList.remove("is-invalid");
        errorEl.style.display = "none";
    }

    // 🔒 Block submit if invalid
    form.addEventListener("submit", function (ev) {
        const val = phoneInput.value.trim();

        if (val && !isValidPhone(val)) {
            ev.preventDefault();
            ev.stopPropagation();
            showError();
            phoneInput.focus();
            return false;
        }
    });

    // Live validation
    phoneInput.addEventListener("input", function () {
        const val = phoneInput.value.trim();
        if (!val || isValidPhone(val)) {
            clearError();
        } else {
            showError();
        }
    });

});
